/** Traced Thuluth calligraphy. Regenerated by `scripts/calligraphy-build.mjs` from `public/media/calligraphy/source/*`. Empty until the artwork is supplied. */
export type CalligraphyWord = {
  id: string;
  viewBox: "0 0 1200 400";
  /** Filled outline of the word (the visible artwork). */
  outline: string;
  /** Pen centre-lines in writing order (right to left); `width` is the mask stroke width that fully covers the letter. */
  pen: readonly { d: string; width: number }[];
  /** Dots and marks, revealed last. */
  dots: readonly string[];
};
export const calligraphy: Readonly<Record<string, CalligraphyWord>> = {};
